#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <errno.h>
#include <limits.h>

#define MAX_TENANT_ID 64
#define MAX_DB_NAME 128
#define MAX_PATH 4096
#define DATA_ROOT "/var/lib/mtdb/data"

typedef struct {
    char tenant_id[MAX_TENANT_ID];
    char db_name[MAX_DB_NAME];
    int  isolation_level;
    char resolved_path[MAX_PATH];
} db_context_t;

typedef struct {
    char segment[256];
    int  depth;
} path_segment_t;

/* Normalize a single path segment: strip leading/trailing whitespace */
static int normalize_segment(const char *input, char *output, size_t outlen) {
    const char *start = input;
    const char *end;
    size_t len;

    while (*start == ' ' || *start == '\t') start++;
    end = start + strlen(start) - 1;
    while (end > start && (*end == ' ' || *end == '\t')) end--;
    len = (size_t)(end - start + 1);
    if (len >= outlen) return -1;
    memcpy(output, start, len);
    output[len] = '\0';
    return 0;
}

/* Validate tenant ID: alphanumeric and hyphens only */
static int validate_tenant_id(const char *tid) {
    if (!tid || strlen(tid) == 0 || strlen(tid) >= MAX_TENANT_ID)
        return -1;
    for (const char *p = tid; *p; p++) {
        if (!((*p >= 'a' && *p <= 'z') || (*p >= 'A' && *p <= 'Z') ||
              (*p >= '0' && *p <= '9') || *p == '-'))
            return -1;
    }
    return 0;
}

/* Count traversal depth to ensure we stay within tenant boundary */
static int compute_effective_depth(const char *path) {
    int depth = 0;
    char tmp[MAX_PATH];
    char *token, *saveptr;

    strncpy(tmp, path, MAX_PATH - 1);
    tmp[MAX_PATH - 1] = '\0';

    token = strtok_r(tmp, "/", &saveptr);
    while (token != NULL) {
        if (strcmp(token, "..") == 0) {
            depth--;
        } else if (strcmp(token, ".") != 0 && strlen(token) > 0) {
            depth++;
        }
        token = strtok_r(NULL, "/", &saveptr);
    }
    return depth;
}

/* Resolve the database path with tenant isolation enforcement */
static int resolve_db_path(db_context_t *ctx) {
    char candidate[MAX_PATH];
    char normalized_db[MAX_DB_NAME];
    char real_candidate[PATH_MAX];
    char real_root[PATH_MAX];
    int eff_depth;

    if (normalize_segment(ctx->db_name, normalized_db, MAX_DB_NAME) != 0)
        return -1;

    /* Reject names containing null bytes or control characters */
    for (size_t i = 0; i < strlen(normalized_db); i++) {
        if (normalized_db[i] < 0x20 && normalized_db[i] != 0)
            return -1;
    }

    /* Build candidate path */
    int written = snprintf(candidate, MAX_PATH, "%s/%s/%s.db",
                           DATA_ROOT, ctx->tenant_id, normalized_db);
    if (written < 0 || written >= MAX_PATH)
        return -1;

    /* Depth check: ensure net traversal doesn't escape tenant dir */
    eff_depth = compute_effective_depth(normalized_db);
    if (eff_depth < 0)
        return -1;

    /* Resolve symlinks and canonicalize */
    if (realpath(DATA_ROOT, real_root) == NULL)
        return -1;

    /* Key check: verify the resolved path starts with tenant root */
    char tenant_root[MAX_PATH];
    snprintf(tenant_root, MAX_PATH, "%s/%s", real_root, ctx->tenant_id);

    /* Create tenant directory if needed */
    mkdir(tenant_root, 0750);

    if (realpath(candidate, real_candidate) == NULL) {
        /* File doesn't exist yet - validate parent directory */
        char *last_slash = strrchr(candidate, '/');
        if (!last_slash) return -1;
        *last_slash = '\0';
        char real_parent[PATH_MAX];
        if (realpath(candidate, real_parent) == NULL)
            return -1;
        /* Verify parent is within tenant root */
        size_t root_len = strlen(tenant_root);
        if (strncmp(real_parent, tenant_root, root_len) != 0)
            return -1;
        *last_slash = '/';
        strncpy(ctx->resolved_path, candidate, MAX_PATH);
    } else {
        /* File exists - verify it's within tenant root */
        size_t root_len = strlen(tenant_root);
        if (strncmp(real_candidate, tenant_root, root_len) != 0)
            return -1;
        strncpy(ctx->resolved_path, real_candidate, MAX_PATH);
    }

    return 0;
}

/* Public API: open a database for a given tenant */
int mtdb_open(const char *tenant_id, const char *db_name, int flags) {
    db_context_t ctx;
    memset(&ctx, 0, sizeof(ctx));

    if (validate_tenant_id(tenant_id) != 0) {
        fprintf(stderr, "Invalid tenant ID\n");
        return -1;
    }

    strncpy(ctx.tenant_id, tenant_id, MAX_TENANT_ID - 1);
    strncpy(ctx.db_name, db_name, MAX_DB_NAME - 1);
    ctx.isolation_level = flags;

    if (resolve_db_path(&ctx) != 0) {
        fprintf(stderr, "Path resolution failed for tenant %s\n", tenant_id);
        return -1;
    }

    printf("Opening database: %s\n", ctx.resolved_path);
    /* In production: return fd from open(ctx.resolved_path, ...) */
    return 0;
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <tenant_id> <db_name>\n", argv[0]);
        return 1;
    }
    return mtdb_open(argv[1], argv[2], 0);
}
